begin;
set local search_path=public,extensions;
select plan(16);

select ok((select p.prosrc like'%pg_advisory_xact_lock%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission takes an advisory transaction lock');
select ok((select p.prosrc like'%benchmark-cell:%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission uses the benchmark cell lock namespace');
select ok((select regexp_replace(p.prosrc,'[[:space:]]','','g')like'%hashtextextended(''benchmark-cell:''||p_metric_code||'':''||p_segment_key||'':''||p_period_start::text||'':''||p_period_end::text,0)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission lock covers the complete cell key');
select ok((select p.prosrc like'%benchmark-cell:%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'compute uses the same benchmark cell lock namespace');
select ok((select position('pg_advisory_xact_lock'in regexp_replace(p.prosrc,'[[:space:]]','','g'))<position('ifexists(select1frompublic.benchmark_publications'in regexp_replace(p.prosrc,'[[:space:]]','','g'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission locks before sealed-state reload');
select ok((select position('ifexists(select1frompublic.benchmark_publications'in regexp_replace(p.prosrc,'[[:space:]]','','g'))<position('insertintoprivate.benchmark_contributions'in regexp_replace(p.prosrc,'[[:space:]]','','g'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'sealed-state revalidation precedes raw insert');
select ok((select p.prosrc like'%BENCHMARK_CELL_SEALED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'post-seal submission has an explicit denial');
select ok((select position('begin_contract_command'in p.prosrc)<position('pg_advisory_xact_lock'in p.prosrc)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'idempotent replay is checked before mutable cell state');
select ok((select p.prosecdef and p.proconfig::text like'%search_path=%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission retains fixed security-definer boundary');
select ok(not has_function_privilege('anon','public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)','EXECUTE'),'only authenticated callers receive submission execute');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a8100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','benchmark-lock@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b8100000-0000-0000-0000-000000000001','Benchmark Lock Tenant','Benchmark Lock','ACTIVE','a8100000-0000-0000-0000-000000000001');
insert into public.organization_memberships(organization_id,user_id,status,activated_at)values('b8100000-0000-0000-0000-000000000001','a8100000-0000-0000-0000-000000000001','ACTIVE',now());
insert into public.organization_member_roles(membership_id,role_code)select id,'CLIENT_ADMIN'from public.organization_memberships where user_id='a8100000-0000-0000-0000-000000000001';
insert into public.benchmark_privacy_policies(id,steward_organization_id,version,status,minimum_group_size,rounding_increment,minimum_period_days,release_delay_days,policy_snapshot,content_hash,effective_from,created_by,correlation_id)values('c8100000-0000-0000-0000-000000000001','b8100000-0000-0000-0000-000000000001',(select coalesce(max(version),0)+1 from public.benchmark_privacy_policies),'RETIRED',5,10,7,1,'{"version":"LOCK-P1"}',repeat('a',64),'2026-01-01','a8100000-0000-0000-0000-000000000001','d8100000-0000-0000-0000-000000000001');
insert into private.benchmark_computations(id,privacy_policy_id,metric_code,segment_key,period_start,period_end,contributor_count,exact_mean,input_manifest_hash,outcome,correlation_id)values('e8100000-0000-0000-0000-000000000001','c8100000-0000-0000-0000-000000000001','LOCK_METRIC','LOCK_SEGMENT','2026-01-01','2026-01-31',5,30,repeat('b',64),'PUBLISHED','d8100000-0000-0000-0000-000000000002');
insert into public.benchmark_publications(id,computation_id,privacy_policy_id,metric_code,segment_key,period_start,period_end,group_size_band,rounded_mean,methodology,cohort_fingerprint,correlation_id)values('f8100000-0000-0000-0000-000000000001','e8100000-0000-0000-0000-000000000001','c8100000-0000-0000-0000-000000000001','LOCK_METRIC','LOCK_SEGMENT','2026-01-01','2026-01-31','5-9',30,'{"republication":"SEALED"}',repeat('c',64),'d8100000-0000-0000-0000-000000000003');

select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8100000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a8100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);select public.submit_benchmark_contribution('b8100000-0000-0000-0000-000000000001','LOCK_METRIC','LOCK_SEGMENT','2026-01-01','2026-01-31',99,'v2',repeat('d',64),'locked-post-seal')$$,'55000','BENCHMARK_CELL_SEALED','post-seal contribution is denied at runtime');
select is((select count(*)from private.benchmark_contributions where metric_code='LOCK_METRIC'and segment_key='LOCK_SEGMENT'),0::bigint,'denied contribution creates no raw row');
select is((select count(*)from public.audit_events where action='benchmark.contribution.submitted'and organization_id='b8100000-0000-0000-0000-000000000001'),0::bigint,'denied contribution creates no false success audit');
select is((select count(*)from public.event_outbox where event_type='BenchmarkContributionAcceptedV1'and organization_id='b8100000-0000-0000-0000-000000000001'),0::bigint,'denied contribution creates no false success event');
select ok((select regexp_replace(pg_get_functiondef('public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)'::regprocedure),'[[:space:]]','','g')like'%hashtextextended(''benchmark-cell:''||p_metric_code||'':''||p_segment_key||'':''||p_period_start::text||'':''||p_period_end::text,0)%'),'submission lock expression exactly matches compute cell components');
select ok((select pg_get_functiondef('public.compute_anonymized_benchmark(uuid,text,text,date,date,uuid)'::regprocedure)like'%hashtextextended(''benchmark-cell:''||p_metric_code||'':''||p_segment_key||'':''||p_period_start::text||'':''||p_period_end::text,0)%'),'compute lock expression remains identical for serialization');

select*from finish();rollback;
